# Vendored from user submission cab6aa76; original hashes in ../references/submission_cab6aa76/manifest.json.
# RSIdemo packaging changes: relative imports and workspace-local native cache.
"""Optional exact native integer kernels; unsupported inputs use Python unchanged.

The shared library is compiled from the adjacent native_routes.c. Loading never
compiles code or installs dependencies. A release may embed compressed bytes in
LIBRARY_DATA by platform; otherwise an adjacent library or explicit local-test
GOLD_ROUTE_LIBRARY path is used. Search budgets and ordering stay in the caller.
"""
from array import array
import base64
import ctypes
import hashlib
import os
from pathlib import Path
import sys
import tempfile
from .cache import native_cache
import zlib

LIBRARY_DATA = {'win32': '', 'linux': ''}
_LIBRARY = None
_ATTEMPTED = False
STATUS = {'loaded': False, 'contexts': 0, 'evaluations': 0, 'partitions': 0, 'fallbacks': 0}


def _library():
    global _LIBRARY, _ATTEMPTED
    if os.environ.get('GOLD_ROUTE_NATIVE') == '0':
        return None
    if _ATTEMPTED:
        return _LIBRARY
    _ATTEMPTED = True
    try:
        suffix = '.dll' if sys.platform == 'win32' else '.so'
        explicit = os.environ.get('GOLD_ROUTE_LIBRARY')
        packed = LIBRARY_DATA.get(sys.platform)
        if explicit:
            path = Path(explicit)
        elif packed:
            blob = zlib.decompress(base64.b64decode(packed))
            digest = hashlib.sha256(blob).hexdigest()[:20]
            path = native_cache() / ('gold_native_routes_' + digest + suffix)
            if not path.exists() or hashlib.sha256(path.read_bytes()).digest() != hashlib.sha256(blob).digest():
                descriptor,temporary = tempfile.mkstemp(prefix=path.name+'.',suffix='.tmp',dir=path.parent)
                try:
                    with os.fdopen(descriptor,'wb') as stream:
                        stream.write(blob)
                    try:
                        os.replace(temporary,path)
                    except OSError:
                        # A simultaneous Windows loader may already hold the
                        # complete DLL. Accept only matching published bytes.
                        if not path.exists() or hashlib.sha256(path.read_bytes()).digest() != hashlib.sha256(blob).digest():
                            raise
                finally:
                    if os.path.exists(temporary):
                        os.unlink(temporary)
        else:
            path = Path(__file__).resolve().with_name('native_routes' + suffix)
        lib = ctypes.CDLL(str(path))
        lib.route_create.argtypes = [ctypes.c_void_p]
        lib.route_create.restype = ctypes.c_void_p
        lib.route_destroy.argtypes = [ctypes.c_void_p]
        lib.route_destroy.restype = None
        lib.route_evaluate.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p]
        lib.route_evaluate.restype = ctypes.c_int
        lib.route_partition.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p, ctypes.c_void_p]
        lib.route_partition.restype = ctypes.c_int
        lib.route_insertions.argtypes = [ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_void_p,ctypes.c_void_p,ctypes.c_void_p]
        lib.route_insertions.restype = ctypes.c_int
        _LIBRARY = lib
        STATUS['loaded'] = True
        STATUS['path'] = str(path)
    except (OSError, ValueError, AttributeError) as exc:
        STATUS['error'] = str(exc)
    return _LIBRARY


def _checked(values):
    if any(not isinstance(v, int) or abs(v) > 1000000 for v in values):
        raise ValueError('native route inputs must be bounded integers')
    return array('i', values)


class NativeMetrics:
    def __init__(self, lib, jobs, workers, shed, last_hour, homes, returning, selective,
                 delivery_jobs, end_service, needs, nets, deadlines, return_empty):
        self.lib = lib
        self.context = None
        self.resources = list(dict.fromkeys(k for group in (needs, nets) for items in group for k in items))
        resources = self.resources
        r = len(resources)
        if len(jobs) > 512 or len(workers) > 64 or r > 64 or not jobs or not workers or not homes:
            raise ValueError('native route dimensions unsupported')
        self.index = {k:i for i,k in enumerate(resources)}
        self.n = len(jobs)
        self.m = len(workers)
        self.r = r
        self.deadlines = deadlines
        self.workers = workers
        if any(q < 0 for need in needs for q in need.values()):
            raise ValueError('negative prefix requirements unsupported')
        cargo = [int(j in delivery_jobs if delivery_jobs is not None else any(op[0] == 'HARVEST' or (last_hour == 22 and op[0] == 'COLLECT_FERTILIZER') for op in job['ops'])) for j, job in enumerate(jobs)]
        data = [len(jobs), len(workers), r, len(homes), last_hour, int(returning), int(selective), end_service, int(return_empty)]
        data += [v for job in jobs for v in job['pos']]
        data += [len(job['ops']) for job in jobs]
        data += list(deadlines) + cargo
        data += [need.get(k,-1) for need in needs for k in resources]
        data += [v for need in needs for v in ([self.index[k] for k in need] + [-1]*(r-len(need)))]
        data += [net.get(k,0) for net in nets for k in resources]
        data += [v for worker in workers for v in (*worker['pos'],worker.get('hour',0),int(any(worker.get('inv',{}).values())))]
        data += [worker.get('inv',{}).get(k,0) for worker in workers for k in resources]
        data += [shed.get(k,0) for k in resources]
        data += [v for home in homes for v in home]
        if any(len(job['pos']) != 2 for job in jobs) or any(len(worker['pos']) != 2 for worker in workers) or any(len(home) != 2 for home in homes):
            raise ValueError('native route coordinates must have two entries')
        self.packed = _checked(data)
        self.stock = _checked([shed.get(k,0) for k in resources])
        self.output = array('i',[0])*(3+2*r)
        self.output_address = self.output.buffer_info()[0]
        self.stock_address = self.stock.buffer_info()[0]
        self.insert_width = 5+2*r
        self.insert_output = array('i',[0]) * ((self.n+self.m)*self.insert_width)
        self.insert_address = self.insert_output.buffer_info()[0]
        self.context = lib.route_create(self.packed.buffer_info()[0])
        if not self.context:
            raise MemoryError('native route context allocation failed')

    def __del__(self):
        if getattr(self,'context',None):
            self.lib.route_destroy(self.context)
            self.context = None

    def evaluate(self, worker, route, enforce=True, reserved=None, pickups=None, travel=False):
        # Creating one compact integer buffer avoids per-element ctypes calls.
        sequence = array('i',route)
        available = None
        if enforce:
            if reserved is None:
                available = self.stock_address
            else:
                stock = array('i',(self.stock[i]-reserved.get(k,0)+pickups.get(k,0) for i,k in enumerate(self.resources)))
                available = stock.buffer_info()[0]
        STATUS['evaluations'] += 1
        if not self.lib.route_evaluate(self.context,worker,sequence.buffer_info()[0],len(sequence),available,self.output_address):
            return None
        out = self.output
        take = {self.resources[out[3+2*i]]:out[4+2*i] for i in range(out[2])}
        return (out[0],take,out[1]) if travel else (out[0],take)

    def partition(self,tour,best_cost):
        sequence = array('i',tour)
        output = array('i',[0])*(2*self.m+1)
        evaluations = ctypes.c_int(0)
        STATUS['partitions'] += 1
        ok = self.lib.route_partition(self.context,sequence.buffer_info()[0],best_cost,output.buffer_info()[0],ctypes.byref(evaluations))
        if ok < 0:
            raise MemoryError('native route partition allocation failed')
        if not ok:
            return None,evaluations.value
        routes = [list(tour[output[w]:output[w+1]]) for w in range(self.m)]
        # Re-evaluate only each selected route to retain exact pickup key order.
        pickups = [self.evaluate(w,route)[1] for w,route in enumerate(routes)]
        ends = list(output[self.m+1:])
        reserved = {}
        for take in pickups:
            for k,q in take.items():
                reserved[k] = reserved.get(k,0)+q
        return (routes,pickups,ends,reserved),evaluations.value

    def insertion(self,job,routes,ends,reserved,pickups,regret=False):
        flat = array('i',(j for route in routes for j in route))
        offsets = array('i',[0])
        for route in routes:
            offsets.append(offsets[-1]+len(route))
        available = array('i',(self.stock[i]-reserved.get(k,0)+take.get(k,0) for take in pickups for i,k in enumerate(self.resources)))
        rows = self.lib.route_insertions(self.context,job,flat.buffer_info()[0],offsets.buffer_info()[0],available.buffer_info()[0],self.insert_address)
        evaluations = len(flat)+len(routes)
        STATUS['evaluations'] += evaluations
        out = self.insert_output
        width = self.insert_width
        best = None
        second = None
        for a in range(rows):
            row = a*width
            worker = out[row]
            finish = out[row+2]
            score = finish-ends[worker]
            if not regret:
                score += 0.035*finish
            if best is None or score < best[0]:
                second = best
                best = (score,row)
            elif second is None or score < second[0]:
                second = (score,row)
        if best is None:
            return None,evaluations
        score,row = best
        worker,k,finish,travel,count = out[row:row+5]
        take = {self.resources[out[row+5+2*i]]:out[row+6+2*i] for i in range(count)}
        if regret:
            choice = (score,worker,k,(finish,take))
            gap = second[0]-score if second is not None else 30
            return (choice,gap),evaluations
        candidate = routes[worker][:k]+[job]+routes[worker][k:]
        return (score,worker,candidate,(finish,take,travel)),evaluations


def make_native(jobs,workers,shed,last_hour,homes,returning,selective,delivery_jobs,
                end_service,needs,nets,deadlines,return_empty=False):
    lib = _library()
    if lib is None:
        STATUS['fallbacks'] += 1
        return None
    try:
        result = NativeMetrics(lib,jobs,workers,shed,last_hour,homes,returning,selective,
                               delivery_jobs,end_service,needs,nets,deadlines,return_empty)
    except (ValueError,TypeError,OverflowError,MemoryError,KeyError) as exc:
        STATUS['fallbacks'] += 1
        STATUS['last_fallback'] = str(exc)
        return None
    STATUS['contexts'] += 1
    return result
